'use strict';
function localDay(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());}
function validResearchDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value;}
function milestoneIsDue(w,m){return w.active&&validResearchDate(m.dueDate||'')&&m.dueDate<=localDay()&&['待核查','延期'].includes(m.status);}
function sourceTimestamp(e){const prefix=e.text.split(/\n\s*\n/).filter(x=>x.trim()).slice(0,e.segment).join('\n\n');const matches=[...prefix.matchAll(/^#{1,6}[^\n]*[（(](\d{1,2}:\d{2}(?:[–—-]\d{1,2}:\d{2})?)[）)]/gm)];return matches.at(-1)?.[1]||'';}
function researchOf(e){return e.research||{timestamp:sourceTimestamp(e),path:[],checks:[]};}
function relevance(e){const text=[e.claim,e.question,e.counter,frame(e.node)?.name].join(' ').toLowerCase();const words=(state.focusKeywords||'').split(/[,，\n]/).map(x=>x.trim()).filter(Boolean);const hit=words.filter(x=>text.includes(x.toLowerCase()));const companyHit=state.companies.filter(c=>text.includes(c.name.toLowerCase())||c.originEntryIds?.includes(e.id)).map(c=>c.name);return [...new Set([...hit,...companyHit])];}
function researchInbox(){const rows=state.entries.map(e=>({e,hits:relevance(e)})).sort((a,b)=>b.hits.length-a.hits.length||b.e.created.localeCompare(a.e.created));const due=state.watches.filter(w=>w.milestones?.some(m=>milestoneIsDue(w,m)));return heading('FROM INFORMATION TO RESEARCH','我的研究线索','日常输入先留下出处，再连接研究对象、核查证据和后续变化。',action('设置关注关键词','focus-edit'))+`<section class="card"><h2>先看与我有关的内容</h2><p>关注：${esc(state.focusKeywords||'尚未设置')}。结合已添加公司的名称和来源关联排序；这是关键词规则，不推断你的实际持仓。</p><p class="muted">${rows.length} 条已归档观点；未命中关注的内容排在后面，仍可找到。</p>${due.length?`<div class="notice warn">${due.length} 个观察主题有到期复核事项（仅在打开页面时检查，不是自动事实预警）。${action('去我的观察','goto','data-area="narrative"','ghost')}</div>`:''}</section>${rows.length?rows.map(({e,hits})=>`<section class="card research-entry"><div class="meta"><span class="pill">${esc(frame(e.node)?.name)}</span><span class="pill ${hits.length?'':'gray'}">${hits.length?'关注命中：'+esc(hits.join('、')):'其他线索 · 保留'}</span></div><h3>${esc(e.claim)}</h3><p>${esc(e.question)}</p><div class="feed-meta">${esc(e.title)} · §${e.segment} · ${esc(researchOf(e).timestamp||'未标时间戳')} · v${e.version}</div><div class="actions">${action('打开研究链路','research-detail',`data-entry="${e.id}"`)}${action('核对原文','source',`data-entry="${e.id}"`,'ghost')}</div></section>`).join(''):empty('先留下一条有出处的观点','导入播客笔记，核对并归档后，它会按关注关键词进入这里。',action('去材料研读','goto','data-area="reader"'))}`;}
function editFocus(){dialog('我的研究关注',`<p>填写行业、公司或研究主题，用逗号分隔。只用于规则排序，不代表持仓。</p><input id="focus-input" maxlength="300" value="${esc(state.focusKeywords||'')}" placeholder="例如：信用,汽车,电池">`,'<button class="primary" id="focus-save">保存关注</button>');$('#focus-save').onclick=()=>{state.focusKeywords=$('#focus-input').value.trim();if(!save())return;closeDialog();render();};}
function companyOriginLinks(c){return (c.originEntryIds||[]).filter(id=>state.entries.some(e=>e.id===id)).map(id=>action('为什么研究它','research-detail',`data-entry="${id}"`,'ghost')).join('');}
function researchDetail(id){const e=state.entries.find(x=>x.id===id);if(!e)return;const r=researchOf(e),cs=state.companies.filter(c=>c.originEntryIds?.includes(id));dialog('从观点到研究对象',`<h3>${esc(e.claim)}</h3><p>${esc(e.title)} · §${e.segment} · ${esc(r.timestamp||'未标时间戳')}</p><div class="notice">观点来自材料，不等于事实成立。传导路径由研究者填写；公司加入表示需要研究，不表示受益或推荐。</div><h3>1. 保存来源位置与传导路径</h3><label for="research-time">纪要中的时间戳（未核验音频）</label><input id="research-time" maxlength="100" value="${esc(r.timestamp)}"><label for="research-path">每行一个环节，保留中间的条件和不确定性</label><textarea id="research-path" rows="5" maxlength="1800">${esc(r.path.join('\n'))}</textarea>${r.path.length?`<ol class="transmission-path">${r.path.map(p=>`<li>${esc(p)}</li>`).join('')}</ol>`:''}<button id="research-save" class="button">保存路径</button><h3>2. 我的研究公司</h3>${cs.map(c=>`<div class="entry"><strong>${esc(c.name)} · ${esc(c.code)}</strong><p>${esc(c.role)}</p><p>${esc(c.reason)}</p></div>`).join('')||'<p>尚未关联公司。先核实业务位置、入选理由和待验证事项。</p>'}<div class="actions">${action('从这条观点添加公司','add-company',`data-entry="${e.id}"`)}<select id="link-company"><option value="">关联已有研究公司</option>${state.companies.filter(c=>!c.originEntryIds?.includes(id)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><button id="link-company-save" class="button">关联</button></div><h3>3. 数据与口径核查</h3><p>先记录指标、期间与单位。接口对照只核对同一观察期的缓存数值；没有匹配期时不拿最新值替代。</p>${r.checks.map(c=>`<article class="entry"><span class="pill ${['数值不同 · 待解释','口径不同 · 不可直接比较','待核实','缺少同期间数据'].includes(c.status)?'warm':''}">${esc(c.status)}</span><h4>${esc(c.label)}</h4><p>材料：${esc(c.claimed)} ${esc(c.unit)} · ${esc(c.period)}<br>${esc(c.reason||'等待填写核查依据')}</p>${c.sourceURL?`<a href="${safeURL(c.sourceURL)}" target="_blank" rel="noopener noreferrer">核查来源 ↗</a>`:''}${c.seriesId? action('按此期间对照缓存','check-series',`data-entry="${id}" data-check="${c.id}"`,'ghost'):''}${action('补充核查依据','entry-check',`data-entry="${id}" data-check="${c.id}"`,'ghost')}${c.history.length?`<details><summary>核查历史（${c.history.length}）</summary>${c.history.map(h=>`<p>${esc(h.time)} · ${esc(h.status)}<br>${esc(h.reason||'')}<br>${esc(h.period||'')} ${esc(h.claimed||'')} ${esc(h.unit||'')}</p>`).join('')}</details>`:''}${c.checkedAt?`<small>核查 ${stamp(c.checkedAt)}</small>`:''}</article>`).join('')}${action('＋ 记录一项核查','entry-check',`data-entry="${id}"`,'ghost')}<h3>4. 后续观察与反证</h3><p>验证：${esc(e.question)}<br>重新判断条件：${esc(e.counter)}</p><div class="actions">${action('从这条观点建立观察','entry-watch',`data-entry="${id}"`)}${action('核对原文','source',`data-entry="${id}"`,'ghost')}${action('修订观点','edit-entry',`data-entry="${id}"`,'ghost')}</div>`);$('#research-save').onclick=()=>{e.research={...r,timestamp:$('#research-time').value.trim(),path:$('#research-path').value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,12)};e.history.push({time:now(),type:'更新研究路径',before:r.path,after:e.research.path});if(!save())return;researchDetail(id);};$('#link-company-save').onclick=()=>{const c=state.companies.find(c=>c.id===$('#link-company').value);if(!c)return;c.originEntryIds=[...new Set([...(c.originEntryIds||[]),id])];if(!save())return;researchDetail(id);};}
function editCheck(id,checkId){const e=state.entries.find(e=>e.id===id);if(!e)return;const previous=e.research?.checks.find(c=>c.id===checkId);dialog('记录指标与口径核查',`<label>核查项<input id="check-label" maxlength="180"></label><div class="form-row"><label>材料中的值或两种表述<input id="check-value" maxlength="150"></label><label>单位<input id="check-unit" maxlength="60" placeholder="例如 %、天、辆"></label></div><label>观察期（按接口对照须精确到 YYYY-MM 或 YYYY-MM-DD）<input id="check-period" maxlength="100"></label><label>可选数据序列<select id="check-series"><option value="">手工核对原始发布 / 未接接口</option>${remote.catalog.filter(s=>s.kind==='series').map(s=>`<option value="${s.id}">${esc(s.name)} (${esc(s.unit)})</option>`).join('')}</select></label><label>核查状态<select id="check-status">${['待核实','原始发布抽样一致','口径不同 · 不可直接比较','可能取整 · 待核原始值','反向线索 · 待验证','缺少定义或公式'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>依据与限制（含来源位置/日期）<textarea id="check-reason" maxlength="2000"></textarea></label><label>来源链接（可选）<input id="check-url" maxlength="1500"></label><p class="error" id="check-error"></p>`,`<button class="primary" id="check-save">保存核查项</button>`);if(previous){for(const [field,key]of Object.entries({label:'label',value:'claimed',unit:'unit',period:'period',reason:'reason',url:'sourceURL',series:'seriesId'}))$('#check-'+field).value=previous[key];if([...$('#check-status').options].some(o=>o.value===previous.status))$('#check-status').value=previous.status;}$('#check-save').onclick=()=>{const c={id:previous?.id||uid(),label:$('#check-label').value.trim(),claimed:$('#check-value').value.trim(),unit:$('#check-unit').value.trim(),period:$('#check-period').value.trim(),seriesId:$('#check-series').value,status:$('#check-status').value,reason:$('#check-reason').value.trim(),sourceURL:$('#check-url').value.trim(),history:[]};if(!c.label||!c.claimed||!c.unit||!c.period||!c.reason||(c.sourceURL&&safeURL(c.sourceURL)==='#'))return $('#check-error').textContent='请补齐指标、材料值、单位、观察期和依据；链接必须为 http(s)。';e.research=researchOf(e);if(previous){c.history=[...previous.history,{time:now(),status:previous.status,reason:previous.reason,claimed:previous.claimed,unit:previous.unit,period:previous.period,sourceURL:previous.sourceURL}];c.checkedAt=now();e.research.checks[e.research.checks.indexOf(previous)]=c;}else e.research.checks.push(c);if(!save())return;researchDetail(id);};}
function checkSeries(id,checkId){const e=state.entries.find(e=>e.id===id),c=e?.research?.checks.find(x=>x.id===checkId);if(!c)return;const s=remote.sources[c.seriesId],p=s?.points?.find(p=>p.date===c.period),v=Number(c.claimed),previous={status:c.status,reason:c.reason,claimed:c.claimed,unit:c.unit,period:c.period,sourceURL:c.sourceURL};if(!s||!p){c.status='缺少同期间数据';c.reason='没有该观察期数据；不以最新观察值替代。';}else if(c.unit!==s.unit||!c.claimed.trim()||!Number.isFinite(v)){c.status='口径不同 · 不可直接比较';c.reason=`接口单位 ${s.unit}；请检查材料值是单一数字，并核实指标定义及日期。`;}else{c.status=Math.abs(v-p.value)<0.005?'缓存数值一致 · 仍需核口径':'数值不同 · 待解释';c.reason=`${s.name} / ${c.period} = ${p.value} ${s.unit}；来源状态 ${s.status}，获取 ${stamp(s.fetchedAt)}。仅比较数值，不证明盘中/日终、定义或因果一致。`;c.sourceURL=s.url;}c.checkedAt=now();c.history.push({time:c.checkedAt,...previous});if(!save())return;researchDetail(id);}
function watchFromEntry(id){const e=state.entries.find(e=>e.id===id);if(!e)return;const existing=state.watches.find(w=>w.entryId===id);if(existing){closeDialog();go('narrative');narrativeTab='watches';render();return;}dialog('从观点建立观察',`<p>将保留原观点关联，之后可添加行业/叙事里程碑。</p><h3>${esc(e.claim)}</h3><label>新闻标题关键词<input id="entry-watch-words" maxlength="250" value="${esc(e.keywords||'')}"></label><p class="error" id="entry-watch-error"></p>`,'<button class="primary" id="entry-watch-save">确认建立</button>');$('#entry-watch-save').onclick=()=>{const keywords=$('#entry-watch-words').value.trim();if(!keywords)return $('#entry-watch-error').textContent='请填写至少一个关键词';state.watches.push({id:uid(),entryId:id,title:e.claim,question:e.question,counter:e.counter,node:e.node,keywords,active:true,seen:[],created:now(),milestones:[]});if(!save())return;closeDialog();go('narrative');narrativeTab='watches';render();};}
function addMilestone(id){const w=state.watches.find(w=>w.id===id);if(!w)return;dialog('自定义行业 / 叙事里程碑',`<label>可观察的事件或指标条件<input id="milestone-title" maxlength="300" placeholder="例如：居民贷款余额同比按统一口径转正"></label><label>判定规则、来源与反证<textarea id="milestone-rule" maxlength="1800" placeholder="说明观察窗口、阈值依据；不知道阈值时写待定，不填任意 X"></textarea></label><label>下次人工复核日<input type="date" id="milestone-due"></label><p>到期只在页面提示复核，不自动判断事件已经发生，不发送站外通知。</p><p class="error" id="milestone-error"></p>`,'<button class="primary" id="milestone-add">保存里程碑</button>');$('#milestone-add').onclick=()=>{const title=$('#milestone-title').value.trim(),note=$('#milestone-rule').value.trim(),dueDate=$('#milestone-due').value;if(!title||!note||!validResearchDate(dueDate))return $('#milestone-error').textContent='请填写可观察条件、规则及复核日';w.milestones||=[];w.milestones.push({title,note,rule:note,dueDate,status:'待核查',history:[{time:now(),status:'待核查',note:'建立观察规则：'+note}]});if(!save())return;closeDialog();render();};}
function milestoneDueLabel(w){const n=(w.milestones||[]).filter(m=>milestoneIsDue(w,m)).length;return n?`<span class="pill warm">${n} 项到期复核 · 未自动判定</span>`:'';}

function validateResearchExtras(kind,x){
 const strings=(obj,keys)=>keys.every(k=>typeof obj[k]==='string');
 if(kind==='entries'&&x.research){const r=x.research;if(!strings(r,['timestamp'])||!Array.isArray(r.path)||r.path.length>12||r.path.some(p=>typeof p!=='string')||!Array.isArray(r.checks)||r.checks.length>100||r.checks.some(c=>!c||!strings(c,['id','label','claimed','unit','period','seriesId','status','reason','sourceURL'])||!Array.isArray(c.history)))throw Error('研究路径或核查项格式错误');}
 if(kind==='companies'&&x.originEntryIds&&(!Array.isArray(x.originEntryIds)||x.originEntryIds.some(id=>typeof id!=='string')))throw Error('公司来源关联格式错误');
 if(kind==='watches'&&x.milestones?.some(m=>m.dueDate!==undefined&&(typeof m.dueDate!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(m.dueDate))))throw Error('里程碑复核日期格式错误');
}

function companyLivePrices(id){
 const c=state.companies.find(c=>c.id===id);if(!c)return;
 const supported=remote.catalog.some(s=>s.kind==='financial'&&s.symbol?.split('.')[0]===c.code);
 const end=new Date();end.setDate(end.getDate()-1);const start=new Date(end);start.setDate(start.getDate()-180);const day=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(d);
 dialog(`${c.name} · 公开历史价格`,`<p>按代码 ${esc(c.code)} 获取东方财富日线，通过本地 TA-Lib 计算。复权价格可能随后续公司行动修订；本次结果保留获取时间，不代表当时可获知的历史快照。</p><div class="form-row"><label>开始日期<input id="quote-start" type="date" value="${day(start)}"></label><label>结束日期<input id="quote-end" type="date" value="${day(end)}" max="${day(end)}"></label></div><label>复权口径<select id="quote-adjustment"><option>前复权</option><option>后复权</option><option>不复权</option></select></label><label><input id="quote-force" type="checkbox">尝试更新（默认复用本日同口径缓存）</label><p>最多730天；不含当天未收盘数据。只有实际返回的交易日进入计算，不补齐停牌或休市日。</p>${!supported?'<div class="notice warn">此代码尚未支持；可使用有来源的CSV导入。</div>':''}${!online?'<div class="notice warn">需要启动本地服务才能获取和计算。</div>':''}<p class="error" id="quote-error"></p>`,`<button class="primary" id="quote-fetch" ${online&&supported?'':'disabled'}>获取并预览</button>`);
 $('#quote-fetch').onclick=async()=>{const button=$('#quote-fetch'),error=$('#quote-error');button.disabled=true;const payload={code:c.code,start:$('#quote-start').value,end:$('#quote-end').value,adjustment:$('#quote-adjustment').value,force:$('#quote-force').checked};try{
  const q=await api('/api/prices',payload);
  if(!button.isConnected)return;const t=q.technical;
  dialog('确认历史行情与计算结果',`<div class="notice ${q.cacheState==='stale'?'warn':''}">${q.cacheState==='fresh'?'本次获取成功':q.cacheState==='same-day-cache'?'使用本日同口径缓存':esc(q.refreshError)}<br>接口对象：${esc(q.company)} ${esc(q.code)}；请核对与研究对象一致。尚未覆盖你的旧结果。</div><p>${esc(q.source)} · ${esc(q.adjustment)} · ${esc(q.currency)}<br>请求 ${esc(q.requestedStart)} — ${esc(q.requestedEnd)}<br>实际 ${esc(t.firstDate)} — ${esc(t.asOf)} · ${t.rows} 条<br>获取 ${stamp(q.fetchedAt)}</p><p>收盘 ${t.close} · MA20 ${t.ma20??'样本不足'} · RSI14 ${t.rsi14??'样本不足'}</p><p>MACD由本次窗口初始化，不同起始窗口可能影响计算结果；统一日期和复权仍不代表完整可比。</p><a href="${safeURL(q.sourceURL)}" target="_blank" rel="noopener noreferrer">查看来源 ↗</a>`,`<button class="button" id="quote-csv">下载本次CSV</button><button class="primary" id="quote-save">确认保存结果</button>`);
  $('#quote-csv').onclick=()=>download(`${q.code}-${q.adjustment}-${t.asOf}.csv`,q.csv);
  $('#quote-save').onclick=()=>{c.history.push({time:now(),type:'获取公开历史价格',before:c.technical||null});const prevTechnical=c.technical;c.technical={...t,code:q.code,source:q.source+' · '+q.sourceURL+' · 获取 '+q.fetchedAt,sourceURL:q.sourceURL,adjustment:q.adjustment,currency:q.currency,fetchedAt:q.fetchedAt,cacheState:q.cacheState,requestedStart:q.requestedStart,requestedEnd:q.requestedEnd};if(!persist(()=>{c.technical=prevTechnical;c.history.pop();}))return;closeDialog();subtab='compare';render();toast('已保存公开日线计算；旧结果保留在记录历史中');};
 }catch(e){if(error.isConnected){error.textContent=e.message;button.disabled=false;}}};
}
